import attrs

@attrs.frozen
class EmailAddress:
    value: str = attrs.field(converter=lambda s: s.strip().lower())

    @value.validator
    def _check(self, attribute, value):
        if "@" not in value:
            raise ValueError(f"not an email address: {value!r}")
